// base already supports variant + size props
function Button({ variant = "secondary", size = "md", className = "", ...rest }: ButtonProps) {
  return <button className={`btn btn--${variant} btn--${size} ${className}`} {...rest} />;
}

// the PR adds a chain, each layer presets one value and nothing else:
+function FancyButton(props: ButtonProps) {
+  return <Button variant="primary" {...props} />;
+}
+function SuperFancyButton(props: ButtonProps) {
+  return <FancyButton size="lg" {...props} />;
+}
+function CtaButton(props: ButtonProps) {
+  return <SuperFancyButton className="btn--cta" {...props} />;
+}
